'use strict';
for(const e of E_ARTICLES)if(!C_ESSAYS.some(x=>x.slug===e.slug))C_ESSAYS.push({slug:e.slug,title:e.title,tag:e.tag,intro:e.dek,paragraphs:[]});
const eHref=e=>'/perspectivas/'+e.slug+'/';
const eLinkSource=(key,label)=>`<a href="${E_SOURCES[key].url}" target="_blank" rel="noopener">${label||E_SOURCES[key].name} ↗</a>`;
function eArt(kind){
let content='';
if(kind==='bridge')content=`<g fill="none" stroke="#b99bcf" stroke-width="1">${Array.from({length:15},(_,i)=>`<path class="e-line" style="--i:${i}" d="M${40+i*11} 360V${235-i*5}Q${40+i*11} ${105-i*3} 255 ${105-i*3}H${430+i*7}Q${525+i*2} ${105-i*3} ${525+i*2} ${235-i*3}V360"/>`).join('')}</g><path d="M135 360V240a120 120 0 0 1 240 0v120" fill="none" stroke="#744a96" stroke-width="48"/><path d="M375 360V240a120 120 0 0 0-20-67" fill="none" stroke="#f59b51" stroke-width="48"/><circle cx="490" cy="312" r="42" fill="#e9c94e"/><path d="M50 386H580" stroke="#bda9ca"/>`;
if(kind==='agency')content=`<g fill="none" stroke="#a18ab5">${[90,140,190].map((r,i)=>`<ellipse cx="315" cy="220" rx="${r}" ry="${r*.6}" transform="rotate(${i*55-55} 315 220)"/>`).join('')}</g><g class="e-orbit"><circle cx="315" cy="30" r="16" fill="#f2c74d"/><circle cx="505" cy="220" r="6" fill="#e7c1ff"/></g><path d="M265 145h100v150H265z" fill="#aa86c4"/><path d="M365 145l34-22v150l-34 22z" fill="#73518d"/><path d="M265 145l34-22h100l-34 22z" fill="#d4bfe2"/><circle cx="315" cy="218" r="30" fill="#f4a05e"/><path d="M300 218l10 10 20-23" fill="none" stroke="#442252" stroke-width="3"/>`;
if(kind==='decision')content=`<g fill="none" stroke="#9372a8" stroke-width="2"><path d="M45 220H180L300 95H430L550 220H600M180 220l120 125h130l120-125"/><path class="e-line" d="M45 220H180L300 95H430L550 220H600" stroke="#ed8b48" stroke-width="4"/></g><path d="M300 30l85 65-85 65-85-65z" fill="#794d9a"/><path d="M300 50l60 45-60 45-60-45z" fill="none" stroke="#c4a5d7"/><text x="300" y="103" fill="white" text-anchor="middle" font-size="26">v2</text><circle cx="75" cy="220" r="24" fill="#e2d5eb"/><circle cx="550" cy="220" r="32" fill="#f29b51"/><rect x="320" y="320" width="100" height="50" fill="#e1d1e9"/><text x="370" y="350" text-anchor="middle" fill="#745187" font-size="14">revisão</text>`;
if(kind==='data')content=`<g fill="none" stroke="#aa8abf" stroke-width="2">${[0,1,2,3,4].map(i=>`<path class="e-line" d="M45 ${80+i*65}H${155+i*16}Q260 ${80+i*65} 300 220H570"/>`).join('')}</g>${[0,1,2,3,4].map(i=>`<circle cx="45" cy="${80+i*65}" r="${12+i*2}" fill="${i%2?'#eabf57':'#a585bb'}"/>`).join('')}<path d="M340 95l120 70v130l-120 70-120-70V165z" fill="#71488e"/><path d="M220 165l120 70 120-70M340 235v130" fill="none" stroke="#ae8cc3"/><path d="M275 180l65-38 65 38-65 38z" fill="#f3a45f"/><text x="340" y="408" fill="#83638f" text-anchor="middle" font-size="11" letter-spacing="3">CONTEXTO → PRODUTO</text>`;
if(kind==='resilience')content=`<g fill="none" stroke-width="2"><path d="M55 220H185L305 95H430L555 220" stroke="#b9a0ca" stroke-dasharray="3 8"/><path class="e-line" d="M55 220H185L305 345H430L555 220H600" stroke="#eea457"/></g><circle cx="70" cy="220" r="25" fill="#cdb4dc"/><circle cx="555" cy="220" r="25" fill="#cdb4dc"/><rect x="310" y="59" width="90" height="72" fill="#5b406d"/><path d="M340 80l28 28m0-28-28 28" stroke="#ef9b67" stroke-width="3"/><rect x="310" y="309" width="90" height="72" fill="#e5b958"/><path d="M340 345l12 12 25-28" stroke="#614353" stroke-width="3" fill="none"/><text x="355" y="176" fill="#ceb9db" font-size="12" text-anchor="middle">indisponível</text><text x="355" y="414" fill="#ceb9db" font-size="12" text-anchor="middle">alternativa validada</text>`;
return `<svg viewBox="0 0 640 440" role="img" aria-label="${{bridge:'Estrutura conectando uma base existente a uma nova capacidade',agency:'Uma ação delimitada por contexto e responsabilidade',decision:'Política versionada separa resultado e revisão',data:'Fontes se organizam em um contexto de produto',resilience:'Dependência indisponível e um percurso alternativo'}[kind]}">${content}</svg>`}
function eCard(e,i){return `<article class="e-story e-story-${e.art}" data-e-topic="${e.topic}"><a class="e-story-visual" href="${eHref(e)}" aria-label="Ler ${ce(e.title)}">${eArt(e.art)}<span class="e-issue">0${i+1}</span></a><div class="e-story-copy"><span class="label">${e.tag}</span><h2><a href="${eHref(e)}">${e.title}</a></h2><p>${e.short}</p><a class="text-link" href="${eHref(e)}">Leia a análise <span>↗</span></a></div></article>`}
function eIndex(){return `<div class="e-page"><section class="e-index-hero wrap"><div class="e-edition"><span>CATALISA / PERSPECTIVAS</span><span>CADERNO 01 · OUTUBRO 2026</span></div><div class="e-headline"><h1>O mercado muda.<br><em>O que vale construir?</em></h1><p>Leituras sobre as demandas que chegam à arquitetura: eficiência, crédito, inteligência artificial e continuidade da operação.</p></div><div class="e-cover"><div><span class="label">A pergunta desta edição</span><h2>Como entregar o próximo<br>produto sem multiplicar<br>a complexidade?</h2><p>Comece por uma responsabilidade que possa evoluir. Depois, conecte contexto, operação e evidência de resultado.</p>${ca(eHref(E_ARTICLES[0]),'Leia a perspectiva de abertura')}</div><div class="e-cover-art">${eArt('bridge')}</div></div><div class="e-cover-footer"><span>FONTES PRIMÁRIAS + LEITURA EDITORIAL + APLICAÇÃO PRÁTICA</span><button data-e-motion aria-pressed="false">Pausar movimento Ⅱ</button></div></section>
<section class="e-signals"><div class="wrap"><div class="e-section-intro"><span class="label">Sinais que orientam a pauta</span><p>Indicadores com período e origem.<br>Interpretações com autoria explícita.</p></div><div class="e-signal-grid"><article><span class="e-big">83<span>%</span></span><p>das transações bancárias ocorreram em canais digitais em 2025.</p><small>Pesquisa Febraban 2026 · ano-base 2025</small>${eLinkSource('feb','Consulte o levantamento')}</article><article><span class="e-big">31<span> bi</span></span><p>de reais em crédito com análise de dados do Open Finance.</p><small>BC · acumulado de 2021 a jun 2025</small>${eLinkSource('bc','Entenda o recorte')}</article><article><span class="e-big">12<span> práticas</span></span><p>para orientar a adoção responsável de IA em instituições financeiras.</p><small>FSB · relatório final de 15 out 2026</small>${eLinkSource('fsb','Leia a publicação')}</article></div></div></section>
<section class="e-reading wrap" id="leituras"><div class="e-library-head"><div><span class="label">Cinco leituras. Decisões concretas.</span><h2>Escolha a pergunta<br>da sua operação.</h2></div><nav aria-label="Filtrar perspectivas">${[['all','Todas'],['modernizacao','Modernização'],['credito','Crédito & dados'],['ia','IA aplicada'],['operacao','Operação']].map(([v,n])=>`<button data-e-filter="${v}" aria-pressed="${v==='all'}">${n}</button>`).join('')}</nav></div><p id="e-count" class="e-count" role="status">5 leituras disponíveis</p><div class="e-stories">${E_ARTICLES.map(eCard).join('')}</div></section>
<section class="e-agenda"><div class="wrap"><span class="label">Do sinal à decisão de arquitetura</span><h2>O que a demanda<br>muda no desenho?</h2><div class="e-matrix">${[['Entrega mais rápida','Mudanças que não dependam de alterar todos os canais.','Contratos e capacidades reutilizáveis',0],['Crédito com contexto','Dados suficientes e uma política que trate exceções.','Fontes, decisão, cálculo e formalização',3],['IA com resultado','Uma tarefa concluída e confirmada, além da resposta.','Ferramentas, estados e responsabilidades',1],['Operação contínua','Saber o que espera, o que falha e o que pode ser repetido.','Dependências e recuperação explícitas',4]].map(([a,b,c,i])=>`<a href="${eHref(E_ARTICLES[i])}"><h3>${a}</h3><p>${b}</p><span>${c} ↗</span></a>`).join('')}</div><p class="e-editor-note">Nossa leitura: essas demandas favorecem fronteiras claras e composição. As fontes contextualizam o mercado; não endossam a Catalisa nem comprovam resultados da plataforma.</p></div></section><section class="e-method wrap"><div><span class="label">Como este caderno foi construído</span><h2>Fonte, análise<br>e hipótese têm<br>lugares diferentes.</h2></div><div><p>Selecionamos publicações de Febraban/Deloitte, Banco Central, FSB, Bank of England e GOV.UK. Os períodos dos dados estão preservados; projeções não são apresentadas como resultados realizados.</p><p>Cada leitura distingue evidência externa, interpretação editorial e exemplos propostos. As métricas são critérios para avaliar projetos, não promessas de desempenho.</p><small>Pesquisa revisada em 22 de outubro de 2026. Artigos internacionais são referências de contexto, não equivalências regulatórias brasileiras.</small>${ca('/arquitetura/','Conheça a arquitetura da Catalisa')}</div></section></div>`}
function eLab(e){
const demos={bridge:{label:'Observe a diferença',title:'A regra mudou. Quem precisa mudar junto?',states:[['Regra duplicada','App, portal e mesa mantêm sua própria interpretação. A mesma alteração precisa percorrer três implementações e três agendas de entrega.',['App: regra A','Portal: regra A','Mesa: regra A']],['Capacidade compartilhada','Os canais consomem um contrato comum. A capacidade concentra a responsabilidade; a mudança ainda exige compatibilidade e testes.',['App','Cálculo comum','Mesa + portal']]]},agency:{label:'Onde está a autoridade?',title:'Consultar, preparar e executar têm limites diferentes.',states:[['Consultar','O agente acessa somente o contexto permitido. A informação precisa ser identificável e pertinente à tarefa.',['Contexto','Permissão','Consulta']],['Preparar','O agente estrutura uma proposta ou um rascunho. O estado deixa claro o que ainda precisa de revisão.',['Evidências','Rascunho','Revisão']],['Executar','Uma ferramenta autorizada realiza a ação no sistema de origem. Só a confirmação permite comunicar a conclusão.',['Autorização','Ferramenta','Confirmação']]]},decision:{label:'Laboratório de política',title:'Uma pendência. Dois percursos possíveis.',states:[['Política A','Neste exemplo, documentação incompleta encaminha o caso à análise humana. A fila recebe motivo e contexto.',['Dados incompletos','Política A','Revisão']],['Política B','Neste exemplo, a jornada solicita complementação antes de encaminhar à mesa. A política muda o trabalho, não apenas a resposta.',['Dados incompletos','Política B','Complementação']]]},data:{label:'Estados da jornada',title:'O dado só ajuda quando seu estado é conhecido.',states:[['Contexto suficiente','Autorização e dados atendem ao recorte definido. A proposta segue para avaliação da política, sem garantia de aprovação.',['Autorização','Dados suficientes','Avaliação']],['Fonte indisponível','Uma falha de consulta gera uma pendência técnica. A jornada informa o próximo passo em vez de apresentar uma negativa de crédito.',['Consulta','Indisponibilidade','Aguardar / revisar']],['Autorização revogada','Novas consultas não devem ser tratadas como autorizadas. A jornada identifica a mudança e encaminha as ações permitidas.',['Revogação','Interromper acesso','Reorientar jornada']]]},resilience:{label:'Exercício de continuidade',title:'O provedor falhou. E agora?',states:[['Aguardar','Quando a espera é aceitável, preserve o pedido, informe a pendência e defina como retomar.',['Pedido','Pendência','Retomada']],['Usar alternativa','A rota secundária só participa se já foi validada para aquele contrato e contexto.',['Pedido','Alternativa validada','Resultado']],['Revisar estado','Quando o efeito é desconhecido, confirme antes de repetir. Reconciliação pode ser necessária.',['Resultado incerto','Verificar origem','Reconciliar']]]}};
const d=demos[e.art];return `<section class="e-lab" data-e-lab="${e.art}"><div class="wrap"><span class="label">${d.label}</span><h2>${d.title}</h2><div class="e-lab-options" role="tablist" aria-label="Cenários ilustrativos">${d.states.map((st,i)=>`<button role="tab" id="e-lab-tab-${i}" data-e-state="${i}" aria-selected="${i===0}" tabindex="${i===0?0:-1}" aria-controls="e-lab-panel">${st[0]}</button>`).join('')}</div>${d.states.map((st,i)=>`<template data-e-template="${i}"><div class="e-lab-path">${st[2].map((x,j)=>`<div><span>0${j+1}</span><strong>${x}</strong></div>`).join('')}</div><p>${st[1]}</p></template>`).join('')}<div id="e-lab-panel" role="tabpanel" aria-labelledby="e-lab-tab-0"><div class="e-lab-path">${d.states[0][2].map((x,j)=>`<div><span>0${j+1}</span><strong>${x}</strong></div>`).join('')}</div><p>${d.states[0][1]}</p></div><small>Exemplo conceitual para explorar responsabilidades. Não executa integrações, decisões de crédito ou operações reais.</small></div></section>`}
function eArticle(e){let i=E_ARTICLES.indexOf(e);return `<article class="e-page e-article e-theme-${e.art}"><nav class="wrap e-breadcrumb" aria-label="Localização"><a href="/perspectivas/">Perspectivas</a><span>/ ${e.tag}</span></nav><header class="e-article-hero"><div class="wrap"><div class="e-article-title"><span class="label">0${i+1} / ${e.tag}</span><h1>${e.title}</h1><p>${e.dek}</p><div class="e-byline">Editorial Catalisa · 22 out 2026 · ${Math.max(3,Math.ceil(JSON.stringify(e).split(/\s+/).length/220))} min de leitura</div></div><div class="e-article-art">${eArt(e.art)}</div></div></header><div class="wrap e-article-toolbar"><a href="#e-body">Comece a leitura ↓</a><button data-e-motion aria-pressed="false">Pausar movimento Ⅱ</button></div><section class="e-evidence wrap"><div><span class="label">${['bridge','agency','data'].includes(e.art)?'Sinal de mercado':'Questão de arquitetura'}</span><strong>${e.signal}</strong><p>${e.signalLabel}</p>${eLinkSource(e.source)}<small>${E_SOURCES[e.source].date}</small></div><blockquote>${e.thesis}<cite>Leitura editorial da Catalisa</cite></blockquote></section><div class="wrap e-article-grid" id="e-body"><aside class="e-toc"><span class="label">Nesta leitura</span>${e.sections.map((s,i)=>`<a href="#e-section-${i}">0${i+1} / ${s[0]}</a>`).join('')}<a href="#e-aplicacao">Aplicação & avaliação</a><a href="#e-fontes">Fontes & limites</a></aside><div class="e-prose">${e.sections.map((s,i)=>`<section id="e-section-${i}"><span class="e-section-no">0${i+1}</span><h2>${s[0]}</h2>${s.slice(1).map(p=>`<p>${p}</p>`).join('')}${i===0?`<p class="e-inline-source">Referência: ${eLinkSource(e.source)}</p>`:''}${e.art==='data'&&i===2?`<p class="e-inline-source">Sobre revogação: ${eLinkSource('consent')}</p>`:''}</section>`).join('')}</div></div>${eLab(e)}<section class="e-application wrap" id="e-aplicacao"><div><span class="label">Uma aplicação possível</span><h2>${e.exampleTitle}</h2><p>${e.example}</p></div><div class="e-measures"><span class="label">Como avaliar · indicadores sugeridos</span>${e.metrics.map(([t,d])=>`<div><h3>${t}</h3><p>${d}</p></div>`).join('')}</div></section><section class="e-questions"><div class="wrap"><span class="label">Leve para a próxima conversa</span><h2>Três perguntas<br>antes de construir.</h2><ol>${e.questions.map(q=>`<li>${q}</li>`).join('')}</ol></div></section><section class="e-connection wrap"><div><span class="label">A relação com a Catalisa</span><h2>Da leitura<br>à composição.</h2></div><div><p>${e.connection}</p><div>${e.links.map(([u,n])=>ca(u,n)).join('')}</div></div></section><section class="e-sources wrap" id="e-fontes"><div><span class="label">Fontes & limites</span><h2>O que sustenta<br>esta leitura.</h2><p>${e.sourceNote}</p></div><ol>${e.sources.map(k=>`<li>${eLinkSource(k)}<small>${E_SOURCES[k].date}</small></li>`).join('')}</ol></section><nav class="e-next wrap" aria-label="Próximas leituras">${[E_ARTICLES[(i+1)%5],E_ARTICLES[(i+2)%5]].map(x=>`<a href="${eHref(x)}"><span class="label">${x.tag}</span><h3>${x.title}</h3><span>Continue a leitura ↗</span></a>`).join('')}</nav></article>`}
const eOriginalPage=cPage;cPage=function(route,blocks){if(route==='/perspectivas/')return eIndex();const e=E_ARTICLES.find(e=>route===eHref(e));if(e)return eArticle(e);return eOriginalPage(route,blocks)};
if(typeof document!=='undefined')document.addEventListener('DOMContentLoaded',()=>{const root=document.querySelector('.e-page');if(!root)return;document.querySelectorAll('[data-e-filter]').forEach(b=>b.addEventListener('click',()=>{let count=0;document.querySelectorAll('[data-e-filter]').forEach(t=>t.setAttribute('aria-pressed',String(t===b)));document.querySelectorAll('[data-e-topic]').forEach(el=>{el.hidden=b.dataset.eFilter!=='all'&&el.dataset.eTopic!==b.dataset.eFilter;if(!el.hidden)count++});document.getElementById('e-count').textContent=count+' leitura'+(count===1?' disponível':'s disponíveis');document.querySelector('.e-stories').classList.toggle('e-filtered',b.dataset.eFilter!=='all')}));document.querySelectorAll('[data-e-motion]').forEach(b=>b.addEventListener('click',()=>{const on=root.classList.toggle('e-paused');b.setAttribute('aria-pressed',String(on));b.textContent=on?'Retomar movimento ▶':'Pausar movimento Ⅱ'}));const tabs=[...document.querySelectorAll('[data-e-state]')];tabs.forEach((b,i)=>{b.addEventListener('click',()=>{tabs.forEach(t=>{t.setAttribute('aria-selected',String(t===b));t.tabIndex=t===b?0:-1});const panel=document.getElementById('e-lab-panel');panel.innerHTML=document.querySelector(`[data-e-template="${i}"]`).innerHTML;panel.setAttribute('aria-labelledby',b.id)});b.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();let n=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[n].focus();tabs[n].click()})})});
